"""Version-labelled gallery of the actual new files and individual source layers."""
import html
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]/'assets/profile-borders-v2'
items=json.loads((ROOT/'manifest.json').read_text())
cards=[]
for a in items:
    record=json.loads((ROOT/a['layer_manifest']).read_text())
    sources=[('테두리',record['frame'])]+[(f'장식 {i+1:02}',o['file']) for i,o in enumerate(record['ornaments'])]
    links=''.join(f'<a href="{path}" download><img src="{path}" alt="{label}" loading="lazy">{label} PNG</a>' for label,path in sources)
    active=a.get('animation',a['svg'])
    cards.append(f'<article data-tier="{a["tier"]}"><div class="sample"><div class="avatar"></div><img src="{active}" data-active="{active}" data-poster="{a["file"]}" alt="V2 {html.escape(a["name"])}" loading="lazy"></div><h2>{a["id"]:03} · {html.escape(a["name"])}</h2><p>{a["tier"]} · {html.escape(a.get("motion_description","비율을 보존한 정지 테두리"))}</p><a href="{a["file"]}" download>정지 PNG</a> · <a href="{active}" download>SVG</a><details><summary>독립 레이어 보기 ({len(sources)}개)</summary><div class="layers">{links}</div></details></article>')
status='100종 제작 완료' if len(items)==100 else f'{len(items)}종 조립 · 제작 중'
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="asset-version" content="profile-borders-v2"><title>V2 · 새 레이어 프로필 테두리</title><style>*{box-sizing:border-box}body{margin:0;padding:30px;background:#f2f0eb;color:#253143;font:15px system-ui}header{max-width:950px;margin-bottom:28px}h1{font-size:28px}h2{font-size:16px;margin:12px 0 5px}p{line-height:1.7}nav{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}button{padding:8px 13px;border:1px solid #b6c0c5;border-radius:20px;background:white;cursor:pointer}button[aria-pressed=true]{background:#263447;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px}article{background:white;border:1px solid #d9dfe1;border-radius:14px;padding:14px}.sample{position:relative;aspect-ratio:1;background:#e0e5e9;border-radius:10px}.avatar{position:absolute;width:69.921875%;height:69.921875%;left:15.0390625%;top:15.0390625%;border-radius:50%;background:#a4b6c7}.sample>img{position:absolute;inset:0;width:100%;height:100%}article p{font-size:13px;color:#617184}a,summary{font-size:13px;color:#31647a}summary{cursor:pointer;margin-top:12px}.layers{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding-top:10px}.layers a{background:#e6ebee;padding:6px;border-radius:6px;text-align:center}.layers img{display:block;width:100%;height:70px;object-fit:contain}.dark .sample{background:#152033}.dark .avatar{background:#344b61}.no-avatar .avatar{display:none}.compact .sample{width:128px;height:128px;margin:auto}.compact .grid{grid-template-columns:repeat(auto-fill,minmax(200px,1fr))}[hidden]{display:none!important}</style><header><strong>V2 · '''+status+'''</strong><h1>새 레이어로 제작한 프로필 테두리</h1><p>장식의 가로·세로 비율을 유지해 배치했습니다. 전설은 테두리와 개별 장식을 따로 그린 PNG로 구성하며, 영웅·전설 효과에는 후광과 명암이 있습니다.</p><p>1024×1024 · 중앙 (512, 512) · 안쪽 원 지름 716px · 중앙 완전 투명<br>회색 프로필 원은 미리보기용입니다. ‘독립 레이어’에서 실제 개별 PNG를 확인할 수 있습니다.</p><nav><button data-filter="all" aria-pressed="true">전체</button><button data-filter="normal">일반</button><button data-filter="premium">고급</button><button data-filter="rare">희귀</button><button data-filter="epic">영웅</button><button data-filter="legendary">전설</button></nav><nav><button id="actual-size" aria-pressed="false">128px로 확인</button><button id="pause" aria-pressed="false">정지 PNG로 보기</button><button id="background">배경 밝기 변경</button><button id="avatar">프로필 원 숨기기 / 표시</button></nav></header><main class="grid">'''+''.join(cards)+'''</main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('article').forEach(a=>a.hidden=b.dataset.filter!=='all'&&a.dataset.tier!==b.dataset.filter)});let paused=false;document.querySelector('#pause').onclick=()=>{paused=!paused;document.querySelectorAll('.sample>img').forEach(i=>i.src=paused?i.dataset.poster:i.dataset.active);document.querySelector('#pause').setAttribute('aria-pressed',String(paused));document.querySelector('#pause').textContent=paused?'효과·동작 보기':'정지 PNG로 보기'};document.querySelector('#actual-size').onclick=()=>{const active=document.body.classList.toggle('compact');document.querySelector('#actual-size').setAttribute('aria-pressed',String(active))};document.querySelector('#background').onclick=()=>document.body.classList.toggle('dark');document.querySelector('#avatar').onclick=()=>document.body.classList.toggle('no-avatar');</script></html>'''
(ROOT/'index.html').write_text(page)
print('V2 gallery entries:',len(items))
